package lifequest.settings;
import lifequest.Main;import lifequest.database.UserDAO;import lifequest.model.User;import lifequest.ui.Style;import javax.swing.*;import java.awt.*;
public class SettingsPanel extends JPanel {
 public SettingsPanel(Main m,User u){setBackground(Style.BACKGROUND);setLayout(new BorderLayout(15,15));setBorder(BorderFactory.createEmptyBorder(25,25,25,25));add(Style.title("Settings"),BorderLayout.NORTH);JPanel p=Style.card();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));p.add(Style.label("Username: "+u.getUsername()));p.add(Style.label("Email: "+u.getEmail()));JCheckBox dark=new JCheckBox("Dark Mode",u.isDarkMode()),notes=new JCheckBox("Notifications",u.isNotifications());dark.setBackground(Style.CARD);dark.setForeground(Style.TEXT);notes.setBackground(Style.CARD);notes.setForeground(Style.TEXT);JButton save=Style.button("Save Settings"),reset=new JButton("Reset Progress"),logout=new JButton("Logout");p.add(dark);p.add(notes);p.add(save);p.add(reset);p.add(logout);save.addActionListener(e->{u.setDarkMode(dark.isSelected());u.setNotifications(notes.isSelected());new UserDAO().updateSettings(u.getId(),u.isDarkMode(),u.isNotifications());JOptionPane.showMessageDialog(this,"Settings saved.");});reset.addActionListener(e->{if(JOptionPane.showConfirmDialog(this,"Reset all progress?","Confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION&&new UserDAO().resetProgress(u.getId())){u.setLevel(1);u.setXp(0);u.setCoins(0);u.setHealth(50);u.setFocus(50);u.setDiscipline(50);u.setStrength(50);JOptionPane.showMessageDialog(this,"Progress reset.");}});logout.addActionListener(e->m.logout());add(p,BorderLayout.CENTER);}
}
